        size_t stride = 1;
        for (size_t st = n/2 + 1; st < n; st++) { int prime=1; for(size_t d=2;d*d<=st;d++) if(st%d==0){prime=0;break;} if(prime){stride=st;break;} }
        for (size_t i = 0; i < n; i++) p[i*stride % n] = ((i+1)*stride) % n * 64 / 64;
        // simpler: next = (i+stride)%n
        for (size_t i = 0; i < n; i++) p[i] = ((i+stride) % n);
        volatile size_t idx = 0;
        // warmup
        for (int r = 0; r < 3; r++) { size_t j=0; for (size_t i=0;i<n;i++) j = p[j]; (void)j; }
        int reps = 20;
        double t0 = now_ns();
        size_t j = 0;
        size_t total = (size_t)reps * n;
        for (size_t i = 0; i < total; i++) j = p[j];
        double dt = now_ns() - t0;
        (void)j;
        printf("%-10zu %12.2f %14.2f\n", sizes[s], dt/total*2.6, dt/total);
        free(p);
    }
    return 0;
}
