// Correct pointer-chase latency: p[i] holds the next index; add a serializing fence per iter is not possible in C easily,
// but a dependent-load chain with volatile forces serialization per element.
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

static double now_ns(void){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec*1e9+ts.tv_nsec;}

int main(void){
    size_t sizes[]={4,8,16,32,64,128,256,512,1024,2048,4096,8192,16384,32768,65536,131072,262144,524288,1048576};
    int ns=sizeof(sizes)/sizeof(sizes[0]);
    printf("%-10s %12s %12s\n","WS(KB)","cyc/ld@2.6G","ns/ld");
    for(int s=0;s<ns;s++){
        size_t n=sizes[s]*1024/8; // size_t elements
        size_t *p=aligned_alloc(64,n*sizeof(size_t));
        // cyclic permutation with prime stride to defeat prefetcher
        size_t stride=7; for(size_t st=n/2|1;st<n;st+=2){int pr=1;for(size_t d=3;d*d<=st;d+=2)if(st%d==0){pr=0;break;}if(pr){stride=st;break;}}
        for(size_t i=0;i<n;i++) p[i]=((i+stride)%n)*8; // store byte offsets
        // warm up caches
        volatile char *j=(char*)p;
        for(int r=0;r<3;r++){char*jj=(char*)p;for(size_t i=0;i<n;i++)jj=jj+*(size_t*)jj; j=jj;}
        int reps=10;
        double best=1e18;
        for(int k=0;k<3;k++){
            double t0=now_ns();
            char *jj=(char*)p;
            size_t total=(size_t)reps*n;
            for(size_t i=0;i<total;i++) jj=jj+*(size_t*)jj;
            double dt=now_ns()-t0;
            if(dt<best)best=dt;
        }
        printf("%-10zu %12.2f %12.2f\n",sizes[s],best/((double)reps*n)*2.6,best/((double)reps*n));
        free(p);
    }
    return 0;
}
