#include <stdlib.h>
#include <stdint.h>

static inline uint64_t cntvct(void){uint64_t v;asm volatile("mrs %0, cntvct_el0":"=r"(v));return v;}

int main(void){
    uint64_t timer_freq; asm volatile("mrs %0, cntfrq_el0":"=r"(timer_freq));
    printf("cntfrq_el0 = %llu Hz\n",(unsigned long long)timer_freq);
