        // warmup
        {size_t j=0;for(int r=0;r<3;r++)for(size_t i=0;i<n;i++)j=p[j];sink=j;}
        double best=1e18; int reps=10;
        for(int k=0;k<3;k++){
            uint64_t t0=cntvct();
            size_t j=0; size_t total=(size_t)reps*n;
            for(size_t i=0;i<total;i++) j=p[j];
