// Simple streaming bandwidth: read+write sweep across WS sizes, cntvct timing.
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

static inline uint64_t cntvct(void){uint64_t v;asm volatile("mrs %0, cntvct_el0":"=r"(v));return v;}

int main(void){
    uint64_t freq; asm volatile("mrs %0, cntfrq_el0":"=r"(freq));
    size_t sizes[]={16,64,256,1024,4096,16384,65536};
    printf("%-10s %16s\n","WS(KB)","GB/s (RW)");
    for(unsigned s=0;s<sizeof(sizes)/sizeof(sizes[0]);s++){
        size_t n=sizes[s]*1024/8;
        uint64_t *a=aligned_alloc(64,n*sizeof(uint64_t));
        for(size_t i=0;i<n;i++)a[i]=i;
        // warmup
        for(size_t i=0;i<n;i++)a[i]+=1;
        double best=0;
        for(int k=0;k<3;k++){
            uint64_t t0=cntvct();
            for(int r=0;r<20;r++)for(size_t i=0;i<n;i++)a[i]+=1;
            uint64_t t1=cntvct();
            double sec=(double)(t1-t0)/(double)freq;
            double bytes=20.0*n*8*2; // read+write
            double gbs=bytes/sec/1e9;
            if(gbs>best)best=gbs;
        }
        printf("%-10zu %16.2f\n",sizes[s],best);
        free(a);
    }
    return 0;
}
